'use strict';
const $=id=>document.getElementById(id), KEY='pen-force-annotations-v1';
const fmt=v=>Number(Number(v).toFixed(3));
let params=[],state={version:1,values:{},comments:{},notes:[]},selected='A1',activeNote=null,view='diagram',zoom=1,marking=false,svgSource='',toastTimer;
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2600)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('saved').textContent='✓ 已保存在此浏览器'}catch(e){$('saved').textContent='保存失败，请导出 JSON';toast('浏览器保存不可用，请导出备份')}}
function valid(v){return typeof v==='number'&&Number.isFinite(v)&&v>=0}
function normalize(data){if(!data||data.version!==1||typeof data.values!=='object'||!Array.isArray(data.notes))throw Error();const out={version:1,values:{},comments:{},notes:[]};for(const p of params){if(valid(data.values[p.id]))out.values[p.id]=data.values[p.id];if(typeof data.comments?.[p.id]==='string')out.comments[p.id]=data.comments[p.id].slice(0,2000)}out.notes=data.notes.filter(n=>['diagram','original'].includes(n.view)&&Number.isFinite(n.x)&&Number.isFinite(n.y)&&n.x>=0&&n.x<=1&&n.y>=0&&n.y<=1&&typeof n.text==='string').map((n,i)=>({...n,id:'import-'+i+'-'+Date.now(),text:n.text.slice(0,2000)}));return out}
function renderList(){const count=Object.keys(state.values).length;$('count').textContent=`${count} / ${params.length} 项已填写`;$('bar').style.width=count/params.length*100+'%';const q=$('search').value.trim().toLowerCase(),f=$('filter').value;$('list').replaceChildren();for(const p of params){if(q&&!`${p.id} ${p.name}`.toLowerCase().includes(q))continue;if(f==='pending'&&p.id in state.values)continue;if(!['all','pending'].includes(f)&&!p.id.startsWith(f))continue;const btn=document.createElement('button');btn.className='row'+(selected===p.id&&!activeNote?' current':'');for(const [cl,t] of [['key',p.id],['title',p.name],['result'+(p.id in state.values?'':' empty'),p.id in state.values?fmt(state.values[p.id])+' '+p.unit:'待填']]){const s=document.createElement('span');s.className=cl;s.textContent=t;btn.append(s)}btn.onclick=()=>select(p.id);$('list').append(btn)}$('noteCount').textContent=state.notes.length;$('notes').replaceChildren();state.notes.forEach((n,i)=>{const b=document.createElement('button');b.className='note-row';b.textContent=`${i+1}. ${n.text||'未填写备注'} · ${n.view==='diagram'?'尺寸图':'原图'}`;b.onclick=()=>{if(view!==n.view)switchView(n.view);selectNote(n.id)};$('notes').append(b)})}
function updateDrawing(){document.querySelectorAll('#drawing [data-key]').forEach(t=>{const key=t.dataset.key;t.textContent=t.dataset.label+(key in state.values?' = '+fmt(state.values[key]):'');t.classList.toggle('done',key in state.values);t.classList.toggle('selected',key===selected&&!activeNote)});$('pins').replaceChildren();state.notes.forEach((n,i)=>{if(n.view!==view)return;const b=document.createElement('button');b.className='pin'+(n.id===activeNote?' active':'');b.style.left=n.x*100+'%';b.style.top=n.y*100+'%';b.textContent=i+1;b.title=n.text||'填写备注';b.setAttribute('aria-label','备注 '+(i+1)+' '+n.text);b.onclick=e=>{e.stopPropagation();selectNote(n.id)};$('pins').append(b)})}
function select(id){selected=id;activeNote=null;$('editor').hidden=false;$('noteEditor').hidden=true;const p=params.find(p=>p.id===id);$('badge').textContent=id;$('name').textContent=p.name;$('nominal').textContent=`${p.confirmed?'已确认':p.derived?'几何推导':'未确认占位'} ${Number(p.nominal.toFixed(3))} ${p.unit}`;document.querySelector('label[for=value] em').textContent=p.unit;$('value').value=state.values[id]??'';$('comment').value=state.comments[id]||'';$('error').textContent='';renderList();updateDrawing()}
function selectNote(id){activeNote=id;const n=state.notes.find(n=>n.id===id);$('editor').hidden=true;$('noteEditor').hidden=false;$('noteText').value=n.text;$('noteBadge').textContent='注 '+(state.notes.indexOf(n)+1);renderList();updateDrawing();$('noteText').focus()}
function switchView(v){view=v;$('diagram').classList.toggle('active',v==='diagram');$('original').classList.toggle('active',v==='original');if(v==='diagram'){$('drawing').innerHTML=svgSource;const svg=$('drawing').querySelector('svg');svg.setAttribute('viewBox','0 0 1800 1000');svg.setAttribute('height','1000');svg.querySelectorAll('text').forEach(t=>{const label=t.textContent;const m=label.match(/^⌀?([ABCDHP]\d+)(?:\s|：|$)/);if(m&&params.some(p=>p.id===m[1])){t.dataset.key=m[1];t.dataset.label=label.replace(/\s*=.*/, '');t.setAttribute('tabindex','0');t.setAttribute('role','button');t.setAttribute('aria-label','填写 '+label);t.onclick=e=>{if(marking)return;e.stopPropagation();select(m[1]);$('value').focus()};t.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(m[1]);$('value').focus()}}}})}else{$('drawing').replaceChildren();const img=document.createElement('img');img.src='sketch.jpg';img.alt='用户提供的推力计与笔装配草图';$('drawing').append(img)}updateDrawing()}
function setMark(on){marking=on;document.body.classList.toggle('marking',on);$('noteMode').classList.toggle('primary',on);$('noteMode').textContent=on?'✓ 结束添加备注':'＋ 添加图上备注';$('hint').textContent=on?'点击图上的位置放置备注，然后在右侧输入内容。':'点击蓝色尺寸编号填写数值；也可以在任意位置添加备注。'}
function textSummary(){const lines=['推力计与笔 · 标注尺寸（长度 mm，角度 deg）'];for(const p of params){if(p.id in state.values||state.comments[p.id])lines.push(`${p.id} ${p.name} = ${state.values[p.id]??'未填'} ${p.unit}${state.comments[p.id]?'；'+state.comments[p.id]:''}`)}if(state.notes.length)lines.push('\n图上备注：',...state.notes.map((n,i)=>`${i+1}. [${n.view==='diagram'?'尺寸图':'原图'} ${Math.round(n.x*100)}%, ${Math.round(n.y*100)}%] ${n.text}`));lines.push('\n未填写项仍未确认，不采用暂定值。');return lines.join('\n')}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function exportJSON(){download(new Blob([JSON.stringify({...state,project:'slotted-plate',exportedAt:new Date().toISOString(),parameters:params},null,2)],{type:'application/json'}),'推力计与笔-标注.json')}
async function exportPNG(){const canvas=document.createElement('canvas');canvas.width=1800;const nh=view==='diagram'?1000:Math.round(1800*$('drawing img').naturalHeight/$('drawing img').naturalWidth);if(!nh){toast('图片尚未加载，请稍后再试');return}const extra=state.notes.filter(n=>n.view===view);canvas.height=nh+(extra.length?60+extra.length*35:0);const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);const img=new Image();let url='sketch.jpg';if(view==='diagram'){const svg=$('drawing').querySelector('svg');const clone=svg.cloneNode(true);clone.querySelectorAll('[data-key]').forEach(t=>{t.style.fill=t.dataset.key in state.values?'#23794e':'#19759c'});url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(clone)],{type:'image/svg+xml;charset=utf-8'}))}try{await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=url});ctx.drawImage(img,0,0,1800,nh);ctx.font='bold 19px sans-serif';extra.forEach((n,i)=>{const num=state.notes.indexOf(n)+1;ctx.fillStyle='#b75127';ctx.beginPath();ctx.arc(n.x*1800,n.y*nh,16,0,Math.PI*2);ctx.fill();ctx.fillStyle='white';ctx.textAlign='center';ctx.fillText(num,n.x*1800,n.y*nh+7);ctx.textAlign='left';ctx.fillStyle='#263c31';ctx.font='20px sans-serif';ctx.fillText(num+'. '+n.text.slice(0,100),35,nh+45+i*35)});canvas.toBlob(blob=>{if(blob)download(blob,'推力计与笔-标注图.png')},'image/png')}catch(e){toast('图片导出失败，请导出 JSON 保留记录')}finally{if(view==='diagram')URL.revokeObjectURL(url)}}
async function init(){[params,svgSource]=await Promise.all([fetch('params.json').then(r=>r.json()),fetch('dimensions.svg').then(r=>r.text())]);try{const baseline=await fetch('confirmed.json').then(r=>r.json());const raw=localStorage.getItem(KEY);state=normalize(raw?JSON.parse(raw):baseline);for(const [k,v] of Object.entries(baseline.values)){if(!(k in state.values)||k==='B3'&&state.values[k]===27)state.values[k]=v}for(const [k,v] of Object.entries(baseline.comments))if(!state.comments[k])state.comments[k]=v;save()}catch(e){toast('未能读取旧记录，请导入备份')}switchView('diagram');select('A1');$('value').oninput=()=>{const v=$('value').value;if(v===''){delete state.values[selected];$('error').textContent=''}else if(valid(Number(v))){state.values[selected]=Number(v);$('error').textContent=''}else{$('error').textContent='请输入不小于 0 的有效尺寸';return}save();renderList();updateDrawing()};$('comment').oninput=()=>{state.comments[selected]=$('comment').value;save()};$('clear').onclick=()=>{delete state.values[selected];delete state.comments[selected];save();select(selected)};$('next').onclick=()=>{const i=params.findIndex(p=>p.id===selected),ordered=[...params.slice(i+1),...params.slice(0,i+1)];const p=ordered.find(p=>!(p.id in state.values));if(p){select(p.id);$('value').focus()}else toast('所有尺寸均已填写')};$('diagram').onclick=()=>switchView('diagram');$('original').onclick=()=>switchView('original');$('search').oninput=renderList;$('filter').onchange=renderList;$('noteMode').onclick=()=>setMark(!marking);$('stage').onclick=e=>{if(!marking)return;const r=$('stage').getBoundingClientRect();const n={id:crypto.randomUUID(),view,x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height,text:''};state.notes.push(n);save();selectNote(n.id)};$('noteText').oninput=()=>{const n=state.notes.find(n=>n.id===activeNote);if(n){n.text=$('noteText').value;save();renderList();updateDrawing()}};$('deleteNote').onclick=()=>{state.notes=state.notes.filter(n=>n.id!==activeNote);save();select(selected)};function scale(n){zoom=Math.max(.5,Math.min(3,n));$('stage').style.width=zoom*100+'%';$('fit').textContent=Math.round(zoom*100)+'%'}$('minus').onclick=()=>scale(zoom-.25);$('plus').onclick=()=>scale(zoom+.25);$('fit').onclick=()=>scale(1);$('export').onclick=exportJSON;$('png').onclick=exportPNG;$('copy').onclick=async()=>{const text=textSummary();try{await navigator.clipboard.writeText(text);toast('已复制，粘贴到聊天即可')}catch(e){$('copyText').value=text;$('copyDialog').showModal();$('copyText').select()}};$('closeDialog').onclick=()=>$('copyDialog').close();$('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const incoming=normalize(JSON.parse(await file.text()));if(!confirm('导入将替换当前浏览器中的记录。建议先导出当前记录。继续导入？'))return;state=incoming;save();select('A1');toast('标注记录已导入')}catch(e){toast('文件格式不正确，请选择本页面导出的 JSON')}finally{$('import').value=''}}}
init().catch(()=>toast('页面资源加载失败，请刷新重试'));
